"""Whole linked-list stable mergesort and callback declaration."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='연결 리스트 · 안정 병합 정렬·불변식',
                     sections=sections, questions=questions))


add('lib/list_sort.c', '연결 리스트 정렬 전체: 안정 병합과 양방향 링크 복원',
    '노드의 데이터를 복사하는 대신 next 링크를 다시 연결하여 정렬합니다.',
    '입력 원형 리스트를 NULL 종료 단방향 리스트로 바꿉니다. 원소를 크기1의 정렬 구간으로 넣고 count의 비트에 따라 구간을 병합합니다. 마지막 병합에서 prev와 원형 head 연결을 복원합니다.',
    '정렬 중에는 정상적인 원형 양방향 구조가 유지되지 않습니다. 호출자는 동시 접근을 제어하고 comparator도 임시 prev나 원형 순회에 의존하지 않아야 합니다.',
    [('파일 전체', 'SPDX와 kernel/bug/compiler/export/string/list_sort/list 헤더,내부 merge,merge_final,알고리즘의 상세 주석,공개 list_sort와 export로 구성됩니다. 별도 노드 할당·해제·재귀 호출은 없습니다.'),
     ('merge와 안정성', 'merge는 두 NULL 종료 정렬 구간을 합칩니다. cmp(priv,a,b)<=0이면 a를 선택하며 같은 키에서도 앞선 입력 구간을 우선합니다. head 지역 변수와 tail 이중 포인터로 다음 링크를 채우고 한 구간이 끝나면 남은 구간을 연결합니다. 이 단계에서는 prev를 복원하지 않습니다.'),
     ('최종 병합', 'merge_final은 비교하며 next와 prev를 함께 설정합니다. 한쪽이 소진되면 남은 b를 이어 붙이고 prev를 끝까지 갱신합니다. 마지막 tail->next=head,head->prev=tail로 원형 구조를 완성합니다. 단순 merge 후 별도 전체 prev 복원 순회를 하지 않도록 코드를 분리한 것입니다.'),
     ('동일 노드 비교 콜백', '최종 남은 구간을 연결할 때 u8 count가256회마다0으로 돌아오면 cmp(priv,b,b)를 호출합니다. 순서 비교 결과는 사용하지 않지만 호출자가 cond_resched 등을 주기적으로 수행할 기회를 줍니다. comparator는 같은 노드 두 개를 받는 경우에도 안전해야 하며 모든 호출이 서로 다른 노드의 순서 결정을 뜻하지 않습니다.'),
     ('공개 함수의 시작', 'head->next가 head->prev와 같으면0개 또는1개이므로 그대로 반환합니다. 그 외에는 마지막 노드의 next를NULL로 바꿉니다. 이후 pending은 정렬된 부분 리스트들을 관리하고 각 부분 리스트의 첫 노드 prev를 다음 pending 구간 링크로 재사용합니다.'),
     ('pending 불변식', '부분 리스트 크기는2의 거듭제곱이고 작은 것·새것이 앞에 있습니다. 각 크기에는0..2개의 구간만 유지됩니다. count의 연속된 하위1비트를 건너뛰어 병합 위치를 찾고 필요 시 먼저 병합한 뒤 입력 원소 하나를 새 크기1 구간으로 넣습니다. 항상 같은 크기 두 개가 생기는 즉시 합치는 단순 이진 카운터와는 타이밍이 다릅니다.'),
     ('비트 상태 설명 읽기', '원문은 count의 비트 k,k-1,상위 비트 존재 여부를 사용해6개 상태를 구분합니다. 크기2^k의 구간은2→3과4→5 전이에서 추가되고5→2에서 병합됩니다. 뒤에 충분한 작은 구간이 있을 때 병합하여 마지막 합치기가 심하게 불균형해지지 않도록 합니다. 주석의 캐시·비교 수 주장은 설계 설명이며 여기서 벤치마크를 실행한 결과는 아닙니다.'),
     ('종료와 비교 계약', '입력이 끝나면 작은 pending부터 합치고 마지막 한 번은 merge_final을 사용합니다. comparator는 a가 뒤로 가야 할 때 양수,앞에 두거나 원래 순서를 유지할 때0 이하를 반환합니다. 따라서 -1/0/1뿐 아니라 a.key>b.key의0/1도 가능합니다. 서로 다른 노드의 비교에서 a는 입력상 먼저 있던 구간에서 오며 동등 키의 순서를 보존합니다.'),
     ('복잡도와 메모리', '병합 정렬의 비교 작업은 O(n log n)이며 콜백 자체 비용은 별도입니다. pending 링크를 기존 노드 prev에 저장하고 재귀나 입력 크기만큼의 별도 배열을 만들지 않으므로 추가 알고리즘 저장소는 O(1)입니다. 데이터 객체와 노드 주소는 유지되지만 링크는 바뀝니다. 콜백에서 리스트를 수정하거나 다른 스레드가 동시에 순회하는 안전성을 이 파일이 제공하지 않습니다.')],
    [('동일한 키일 때 merge는 어느 쪽을 먼저 선택하는가?', '먼저 입력된 구간 a를 선택한다', '항상 b를 선택해 순서를 뒤집는다', 'cmp<=0 분기가 a를 선택합니다. 원래 구간의 시간 순서와 이 규칙이 안정성을 유지합니다.'),
     ('정렬 도중 prev는 항상 이전 노드를 가리키는가?', '아니다. pending 부분 리스트를 연결하는 용도로 재사용된다', '그렇다. 모든 중간 단계가 정상 원형 양방향 리스트다', '중간 구간은 NULL 종료 단방향이고 prev는 유지되지 않습니다. 마지막 병합에서 복원합니다.'),
     ('cmp(priv,b,b)를 호출하는 이유는?', '긴 잔여 구간 처리 중 호출자에게 주기적인 실행 기회를 주기 위해서다', '같은 노드를 둘로 복제하기 위해서다', 'u8 카운터가 돌아올 때 호출하며 반환값은 순서 결정에 사용하지 않습니다. 콜백은 같은 인자에도 안전해야 합니다.'),
     ('boolean comparator인 a.key>b.key를 쓸 수 있는가?', '있다. 뒤로 가야 할 때1,그 외0이라는 계약과 맞는다', '없다. 반드시 음수·0·양수 세 값을 모두 반환해야 한다', '이 구현은 안정 병합에서 앞선 구간을 우선하므로 a<b와 a==b를 구분하지 않아도 됩니다.'),
     ('sort.c의 배열 힙 정렬과 달리 보장하는 성질은?', '동일한 키의 입력 순서 유지', '모든 중간 단계의 원형 링크 유지', 'list_sort는 안정 정렬입니다. 중간 링크 구조는 오히려 임시로 변경됩니다.')])

add('include/linux/list_sort.h', '리스트 정렬 헤더 전체: 전방 선언과 nonnull 계약',
    '링크 노드의 정의와 정렬 함수의 선언을 분리한 인터페이스입니다.',
    'struct list_head를 전방 선언하고 list_cmp_func_t와 list_sort를 선언합니다. 둘 다 두 번째·세 번째 인자의 nonnull 속성을 사용합니다.',
    'priv는 첫 번째 인자이므로 이 속성으로 비NULL을 요구하지 않습니다. head와 cmp 또는 comparator의 두 노드 인자는 유효해야 합니다. 속성은 실행 시 NULL 검사를 자동으로 삽입하는 코드가 아닙니다.',
    [('전체 내용', 'SPDX,_LINUX_LIST_SORT_H guard,types.h 포함,list_head 전방 선언,comparator typedef,공개 함수 선언,#endif가 전부입니다. 노드 구조체의 실제 필드나 병합 본문은 이 파일에 없습니다.'),
     ('콜백 인자 순서', 'list_cmp_func_t는 int 반환이며 void* 문맥이 첫 번째,두 const list_head*가 그 뒤입니다. 배열 sort_r의 문맥이 마지막인 comparator와 순서를 혼동하면 안 됩니다. typedef를 무시한 함수 포인터 캐스트는 올바른 호출 계약을 만들지 않습니다.'),
     ('전방 선언과 속성', '포인터 타입을 선언하는 데 구조체의 전체 크기는 필요하지 않아 전방 선언으로 충분합니다. nonnull(2,3)은 컴파일러에 호출 전제를 알리는 속성입니다. list_sort에서는 head와cmp,comparator에서는 두노드가 해당되며 priv는 NULL도 전달할 수 있습니다.'),
     ('사용 범위', '원형 list_head 리스트를 정렬하는 API이며 임의의 배열이나 단방향 노드 구조를 대신 받지 않습니다. 안정성·임시 링크·같은 노드 비교 등 세부 계약은 구현 문서와 함께 읽습니다.')],
    [('nonnull(2,3)이 priv도 반드시 비NULL이라고 뜻하는가?', '아니다. priv는 첫 번째 인자다', '그렇다. 모든 포인터 인자가 자동 포함된다', '속성은 인자 번호를 명시합니다. list_sort의2번head,3번cmp가 해당됩니다.'),
     ('list_head 전방 선언만으로 함수 포인터 선언이 가능한 이유는?', '구조체 포인터 타입에는 전체 필드 배치가 필요하지 않기 때문이다', '전방 선언이 모든 필드를 자동 생성하기 때문이다', '불완전 타입을 가리키는 포인터는 선언할 수 있습니다. 실제 필드 접근에는 별도 정의가 필요합니다.'),
     ('리스트 comparator의 문맥 위치는?', '첫 번째 인자', '마지막 인자', 'typedef가(void*,const list_head*,const list_head*) 순서입니다. 배열 정렬의 콜백과 구분합니다.')])
